t0 = time.monotonic()
ctx = _resolve_context(cli, {"cleanup_timeout": 1.0}, "cli", ["sub"])
dt = time.monotonic() - t0
print(f"1) completion with timeout returned in {dt:.2f}s")
assert dt < 10, dt
assert ctx.cleanup_timeout == 1.0

